<script lang="ts" module>import type{Snippet}from'svelte';import type{RxColor}from'$lib/registry/lib/color';export interface InlineOverflowProps{items:Snippet[];gap?:string;moreLabel?:string;color?:RxColor;priority?:'start'|'end'}</script>
<script lang="ts">import*as Dropdown from'$lib/components/ui/dropdown-menu/index.js';import{styleColor}from'$lib/registry/lib/color';let{items,gap='.5rem',moreLabel='More',color,priority='start'}:InlineOverflowProps=$props();let visible=$state(Number.POSITIVE_INFINITY),root:HTMLElement,more=$state<HTMLButtonElement|null>(null);let frame=0;function fit(){cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{const widths=[...root.querySelectorAll<HTMLElement>('[data-measure]')].map(el=>el.offsetWidth);const available=root.clientWidth;const moreWidth=more?.offsetWidth??60;let used=0,count=0;for(const width of(priority==='start'?widths:[...widths].reverse())){if(used+width+(count?parseFloat(gap):0)>available-moreWidth)break;used+=width+(count?parseFloat(gap):0);count++}const focused=document.activeElement as HTMLElement|null;if(focused?.closest('[data-overflow-index]')){const index=Number(focused.closest<HTMLElement>('[data-overflow-index]')?.dataset.overflowIndex);const willHide=priority==='start'?index>=count:index<items.length-count;if(willHide)more?.focus()}visible=count})}function watch(node:HTMLElement){root=node;const observer=new ResizeObserver(fit);observer.observe(node);queueMicrotask(fit);return()=>{observer.disconnect();cancelAnimationFrame(frame)}}const shown=$derived(priority==='start'?items.slice(0,visible):items.slice(Math.max(0,items.length-visible)));const hidden=$derived(priority==='start'?items.slice(visible):items.slice(0,Math.max(0,items.length-visible)));</script>
<div class="rx-overflow" style={`${styleColor(color)??'--rx-color:var(--rx-primary)'};gap:${gap}`} {@attach watch}>{#each shown as item,i}<span data-overflow-index={priority==='start'?i:Math.max(0,items.length-visible)+i}>{@render item()}</span>{/each}<Dropdown.Root><Dropdown.Trigger bind:ref={more} disabled={!hidden.length} class="rx-overflow__more">{moreLabel} ({hidden.length})</Dropdown.Trigger><Dropdown.Content align="end" class="rx-overflow__menu">{#each hidden as item}<Dropdown.Item class="rx-overflow__entry">{@render item()}</Dropdown.Item>{/each}</Dropdown.Content></Dropdown.Root><span class="rx-overflow__measure" aria-hidden="true">{#each items as item}<span data-measure>{@render item()}</span>{/each}</span></div>
<style>.rx-overflow{position:relative;display:flex;align-items:center;width:100%;min-width:0;white-space:nowrap}.rx-overflow__measure{position:absolute;visibility:hidden;display:flex;gap:inherit;pointer-events:none}:global(.rx-overflow__more){border:0;border-radius:999px;padding:.4rem .65rem;color:rgb(var(--rx-color));background:rgb(var(--rx-color)/.12);font:inherit}:global(.rx-overflow__more:disabled){display:none}:global(.rx-overflow__menu){min-width:10rem;border:1px solid rgb(var(--rx-text)/.08);border-radius:var(--rx-radius);padding:.4rem;background:rgb(var(--rx-background))}:global(.rx-overflow__entry){padding:.5rem .65rem}</style>
